sp_angular_provider.script:
function DHActionFactory(
  $location,
  $window,
  spModal,
  i18n,
  spUtil,
  DHApiFactory,
  snAnalytics,
) {

  const api = DHApiFactory();

  const setupAnalyticsPayload = function (action, device) {
    let event = {
      name: "ADH Action Executed",
      data: {},
    };

    event.data["Action Type"] = action.type;
    event.data["Action Category"] = action.category;
    event.data["Action Title"] = action.title;
    event.data["Device Name"] = device.name;
    event.data["Device Model"] = device.asset_model;

    return event;
  };

  const handlers = {
    /**
     * Handle the execution of a page action
     * @param {Object} action
     */
    page: function (action) {
      let path = $location.path();
      let pageURL = path + "?id=" + action.page_link$DISPLAY;
      if (action.parameters && Object.keys(action.parameters).length > 0) {
        for (let key in action.parameters) {
          pageURL += "&" + key + "=" + action.parameters[key];
        }
      }
      $window.open(pageURL);
    },

    /**
     * Handle the execution of a URL action
     * @param {Object} action
     */
    url: function (action) {
      $window.open(action.url);
    },

    /**
     * Handle the execution of a remote action
     * @param {Object} action
     */
    remote_action: async function (action, device) {
      action.running = true;

      try {
        await api.executeRemoteAction(action.sys_id, device.asset_id);
        action.run_today = true;
        spModal.open({
          title: i18n.getMessage("dh.action.remote.one_time.title"),
          message: i18n.getMessage("dh.action.remote.one_time"),
          buttons: [
            {
              label: i18n.getMessage("OK"),
              primary: true,
            },
          ],
        });
      } catch (e) {
        spUtil.addErrorMessage(
          "An error occurred while executing the action. Please contact the system administrator.<br><br>Error: " +
            e.message,
        );
      }

      action.running = false;
    },

    /**
     * Handle the execution of a client script action
     * @param {Object} action
     */
    client_script: function (action) {
      eval(action.script);
      action.run_today = true;
    },

    /**
     * Handle the execution of a server script action
     * @param {Object} action
     */
    server_script: async function (action, device) {
      action.running = true;

      try {
        var serverScriptResponse = await api.executeActionServerScript(
          action.sys_id,
          device.asset_id,
        );
        action.running = false;
        action.run_today = true;

        spUtil.addInfoMessage(serverScriptResponse.message);
      } catch (e) {
        spUtil.addErrorMessage(
          "An error occurred while executing the action. Please contact the system administrator.<br><br>Error: " +
            e.message,
        );
      }

      action.running = false;
    },
  };

  return {
    /**
     * Handle for executing an action based on its type
     * @param {Object} action
     * @param {Device} device
     */
    executeAction: async function (action, device) {

      switch (action.type) {
        case "page":
          handlers.page(action);
          break;
        case "url":
          handlers.url(action);
          break;
        case "remote_action":
          handlers.remote_action(action, device);
          break;
        case "client_script":
          handlers.client_script(action);
          break;
        case "server_script":
          handlers.server_script(action, device);
          break;
        default:
          console.error("Couldn't match the type for the action", action);
      }

      try {
        const payload = setupAnalyticsPayload(action, device);
        snAnalytics.addEvent(payload);
      } catch (e) {
        console.error("Error generating/sending analytics payload for action execution",e);
      }
    },
  };
}
